package main

import (
    "fmt"
    "os"
)

type Writer interface {
    Write([]byte) int
}

type Logger struct {}

func (l Logger) Write(b []byte) int {
    fmt.Fprintln(os.Stdout, string(b))
    return len(b)
}

func main() {
    logger := Logger{}
    var w Writer = logger
    n := w.Write([]byte("hello"))
    fmt.Print(n, " ")
    fmt.Println(string([]byte("hello")))
}

