exercises.solution:
package main

import (
    "fmt"
    "math"
)

type Shape interface {
    Area() float64
}

type Circle struct {
    Radius float64
}

type Rectangle struct {
    Width  float64
    Height float64
}

func (c Circle) Area() float64 {
    return math.Pi * c.Radius * c.Radius
}

func (r Rectangle) Area() float64 {
    return r.Width * r.Height
}

func main() {
    c := Circle{Radius: 5}
    r := Rectangle{Width: 3, Height: 4}

    var s1 Shape = c
    var s2 Shape = r

    if s1.Area() > s2.Area() {
        fmt.Println(s1.Area())
    } else {
        fmt.Println(s2.Area())
    }
}

