exercises.solution:
package main

import "fmt"

func main() {
    items := []interface{}{
        42,
        "hello",
        3.14,
    }

    for _, item := range items {
        switch v := item.(type) {
        case int:
            fmt.Printf("int: %d\n", v)
        case string:
            fmt.Printf("string: %s\n", v)
        case float64:
            fmt.Printf("float64: %f\n", v)
        }
    }
}
